      "evidence": ["Lib/HIServices/_metadata.py"]
    },
    {
      "name": "打印服务（PrintCore）",
      "description": "封装 macOS PrintCore (PM*) API 全套打印管理功能，包括打印会话（PMSession）、打印设置（PMPrintSettings）、页面格式（PMPageFormat）、打印机管理（PMPrinter）、纸张规格（PMPaper）、预设（PMPreset）和 PDF 工作流，支持打印对话框和 PDF 输出。",
